/* Site configuration. Course settings come from course.config.json via content/course-config.js
 * (generated by `npm run build-course`). Only app-level settings belong here. */
window.Course = window.Course || {};
Course.config = Object.assign({
  appVersion: "0.9.16",          // shown in the footer; bump on every release
  maxAttempts: 0,                // 0 = unlimited (display only in the standalone build)
  storageKey: "daintta-learning-v1",
  totalModules: 0,
  modulesPerStage: [],
  stages: []
}, window.CourseSettings || {});

// SharePoint module documentation links (none in the standalone build)
Course.sharePointDocs = {};
